// Package depcheck compares the files each build step really touched (from
// a traced build) with the dependencies Ninja knows about.
package depcheck

import (
	"path/filepath"
	"sort"
	"strings"

	"github.com/7shantanu7/kiln/internal/ninja"
	"github.com/7shantanu7/kiln/internal/sandbox"
)

// Kinds of findings.
const (
	// A step read a file generated by another step that is not ordered
	// before it. Clean parallel builds can fail or read a stale copy.
	KindRace = "undeclared-generated-input"
	// A step without a depfile read a source file it does not declare.
	// Changing that file will not rebuild the step's outputs.
	KindStale = "undeclared-source-input"
	// A step wrote a file outside the build directory.
	KindOutsideWrite = "write-outside-build-dir"
)

// Finding is one undeclared dependency.
type Finding struct {
	Kind     string `json:"kind"`
	Step     string `json:"step"`               // first output of the step, relative to the build dir
	File     string `json:"file"`               // file read or written
	Producer string `json:"producer,omitempty"` // step that generates File (races only)
}

// Report is the outcome of a check.
type Report struct {
	Findings  []Finding `json:"findings"`
	Steps     int       `json:"steps_traced"`
	Unmatched int       `json:"steps_unmatched"` // traced commands that wrote no known output
	Reads     int       `json:"reads_checked"`
}

// Check matches traced processes to edges and reports undeclared dependencies.
// Only files under srcRoot or the build directory are considered.
func Check(g *ninja.Graph, res *sandbox.Result, srcRoot string) Report {
	var rep Report
	srcRoot = filepath.Clean(srcRoot)
	under := func(p, root string) bool { return p == root || strings.HasPrefix(p, root+"/") }
	inScope := func(p string) bool { return under(p, srcRoot) || under(p, g.Dir) }
	rel := func(p string) string {
		if r, err := filepath.Rel(g.Dir, p); err == nil && !strings.HasPrefix(r, "..") {
			return r
		}
		if r, err := filepath.Rel(srcRoot, p); err == nil && !strings.HasPrefix(r, "..") {
			return "$SRC/" + r
		}
		return p
	}
	// Ninja-internal files are read by Ninja itself, never by steps.
	ignored := func(p string) bool {
		b := filepath.Base(p)
		return b == ".ninja_log" || b == ".ninja_deps" || b == "build.ninja" || strings.HasPrefix(b, ".kiln-")
	}

	// Each child of the root process (Ninja) runs one build step.
	seen := map[string]bool{}
	for _, child := range res.Children(res.Root) {
		var reads, writes []string
		for _, p := range res.Subtree(child) {
			for _, a := range p.Accesses {
				if a.Dir || !inScope(a.Path) || ignored(a.Path) {
					continue
				}
				if a.Write {
					writes = append(writes, a.Path)
				} else {
					reads = append(reads, a.Path)
				}
			}
		}
		edge := matchEdge(g, writes)
		if edge == nil {
			if len(reads)+len(writes) > 0 {
				rep.Unmatched++
			}
			continue
		}
		rep.Steps++
		step := rel(edge.Outputs[0])
		own := map[string]bool{}
		for _, w := range writes {
			own[w] = true
		}
		for _, o := range edge.Outputs {
			own[o] = true
		}
		declared := map[string]bool{}
		for _, in := range edge.StaticInputs() {
			declared[in] = true
		}
		for _, d := range edge.Deps {
			declared[d] = true
		}
		hasDepfile := len(edge.Deps) > 0
		var upstream map[*ninja.Edge]bool
		add := func(f Finding) {
			key := f.Kind + "\x00" + f.Step + "\x00" + f.File
			if !seen[key] {
				seen[key] = true
				rep.Findings = append(rep.Findings, f)
			}
		}
		for _, w := range writes {
			if !under(w, g.Dir) {
				add(Finding{Kind: KindOutsideWrite, Step: step, File: rel(w)})
			}
		}
		for _, r := range dedupe(reads) {
			if own[r] {
				continue
			}
			rep.Reads++
			if g.IsGenerated(r) {
				producer := g.Producer[r]
				if producer == edge {
					continue
				}
				if upstream == nil {
					upstream = g.Upstream(edge)
				}
				if !upstream[producer] {
					add(Finding{Kind: KindRace, Step: step, File: rel(r), Producer: rel(producer.Outputs[0])})
				}
				continue
			}
			// A source file. Steps with a depfile report what they read, so
			// only steps without one can silently miss an input.
			if !declared[r] && !hasDepfile && !strings.HasPrefix(rel(r), "CMakeFiles/") {
				add(Finding{Kind: KindStale, Step: step, File: rel(r)})
			}
		}
	}
	sort.Slice(rep.Findings, func(i, j int) bool {
		a, b := rep.Findings[i], rep.Findings[j]
		if a.Kind != b.Kind {
			return a.Kind < b.Kind
		}
		if a.Step != b.Step {
			return a.Step < b.Step
		}
		return a.File < b.File
	})
	return rep
}

// matchEdge finds the edge whose outputs the step wrote.
func matchEdge(g *ninja.Graph, writes []string) *ninja.Edge {
	for _, w := range writes {
		if e, ok := g.Producer[w]; ok && !e.Phony() {
			return e
		}
	}
	return nil
}

func dedupe(xs []string) []string {
	sort.Strings(xs)
	out := xs[:0]
	for i, x := range xs {
		if i == 0 || x != xs[i-1] {
			out = append(out, x)
		}
	}
	return out
}
